const result = (q, answer, unit, hint, solution, wrong, feedback) => ({q, answer, unit, hint, solution, wrong, feedback});
const n = (seed, mod) => Math.abs(Math.trunc(seed || 0)) % mod;
const round = x => Math.round((x + Number.EPSILON) * 100) / 100;
export const course = {
 title:'R2', intro:'Undersøk rekker, integralregning og modeller gjennom resonnering, programmering og arbeid med data.',
 source:'https://www.udir.no/lk20/mat03-02/kompetansemaal-og-vurdering/kv294?lang=nob',
 chapters:[
 {id:'rekker',title:'Følger og rekker',summary:'Utforsk aritmetiske og geometriske rekker og vurder konvergens.',
 theory:['En følge er en ordnet liste a₁, a₂, …; en rekke er summen av leddene. Aritmetiske følger har konstant differanse d, mens geometriske følger har konstant kvotient k.','For en aritmetisk rekke er Sₙ = n(a₁ + aₙ)/2. For en geometrisk rekke med k ≠ 1 er Sₙ = a₁(1 − kⁿ)/(1 − k). En uendelig geometrisk rekke med a₁≠0 har summen a₁/(1 − k) akkurat når |k| < 1.','En sparemodell kan bruke en geometrisk rekke. Oppgi når innbetalinger og rentetilskriving skjer; beløpets verdi avhenger av tidspunktet.'],
 example:['Summen 100 + 50 + 25 + … har a₁ = 100 og k = 0,5.','Sₙ = 200(1 − 0,5ⁿ).','Når n går mot uendelig, nærmer summen seg 200.'],
 activity:'En ball slippes fra 2 m og spretter hver gang til 70 % av forrige høyde. Undersøk samlet tilbakelagt vei etter n hele sprett (opp og ned) og på lang sikt. Forklar modellen, utled en formel og vurder forutsetningene.',
 criteria:['Utleder og begrunner summen og konvergensen.','Tolker modellen og drøfter dens begrensninger.'],
 model:'Første fall er 2 m. Etter n hele sprett er veien 2 + 4·0,7(1−0,7ⁿ)/(1−0,7) meter. Potensen 0,7ⁿ går mot 0, så den totale veien nærmer seg 11,33 m. Konstant sprettfaktor er en idealisering.',teacher:'Forkunnskaper: potensregning. Vanlig feil: telle hver sprett bare én gang. Be eleven begrunne hvorfor rekken konvergerer.',goals:['Utforske egenskaper ved rekker og gjøre rede for praktiske anvendelser.'],
 task(level,seed){let a=2+n(seed,8),k=2+n(seed,3);if(level===0)return result(`En aritmetisk følge starter med ${a} og har differanse ${k}. Hva er fjerde ledd?`,a+3*k,'','Legg til differansen tre ganger.',`${a}+3·${k}=${a+3*k}.`,a+4*k,'Første ledd er allerede gitt.');if(level===1)return result(`Finn summen av de fire første leddene i den geometriske rekken med første ledd ${a} og kvotient ${k}.`,a*(1+k+k*k+k*k*k),'','Summer de fire leddene.',`${a}·(1+${k}+${k}²+${k}³)=${a*(1+k+k*k+k*k*k)}.`,a*k*k*k,'Dette er bare fjerde ledd.');return result(`En uendelig geometrisk rekke har første ledd ${a} og kvotient 0,5. Finn summen.`,2*a,'','Bruk a₁/(1−k).',`${a}/(1−0,5)=${2*a}.`,a,'Summen inkluderer alle leddene.');}},
 {id:'rekursjon',title:'Rekursjon og programmering',summary:'Undersøk sammenhenger trinn for trinn med kode.',
 theory:['En rekursiv definisjon gir startverdi og en regel for neste ledd, for eksempel a₀ = 100 og aₙ₊₁ = 1,05aₙ + 10.','Et program kan starte med a = 100 og gjenta a = 1.05*a + 10 i en løkke. Teller og oppdateringsrekkefølge bestemmer hvilket ledd som vises.','En stabil likevekt L oppfyller L = f(L). At den finnes, garanterer ikke at alle følger nærmer seg den; undersøk dette analytisk og numerisk.'],
 example:['a₀ = 10 og aₙ₊₁ = 0,5aₙ + 3.','a₁ = 8 og a₂ = 7.','Likevekten oppfyller L = 0,5L + 3, altså L = 6.'],
 activity:'Programmer a₀ = 100 og aₙ₊₁ = 0,8aₙ + 10. Vis kode, tabell og graf for flere startverdier. Finn og begrunn likevekten, undersøk om følgene nærmer seg den, og forklar hvordan programmet virker.',
 criteria:['Presenterer fungerende algoritme med korrekt indeksering.','Begrunner likevekten og sammenligner numeriske resultater.'],
 model:'L = 0,8L + 10 gir L = 50. Differansen fra likevekten oppfyller aₙ₊₁ − 50 = 0,8(aₙ − 50), og går derfor mot 0. En løkke oppdaterer a med 0,8a + 10 for hvert trinn.',teacher:'Forkunnskaper: funksjoner og løkker. Vanlig feil: forveksle a₀ og a₁. Test koden for de to første leddene.',goals:['Utforske rekursive sammenhenger ved programmering og presentere egne framgangsmåter.'],
 task(level,seed){let a=4+2*n(seed,6),b=1+n(seed,5);if(level===0)return result(`a₀=${a} og aₙ₊₁=aₙ+${b}. Hva er a₁?`,a+b,'','Bruk regelen én gang.',`${a}+${b}=${a+b}.`,a+2*b,'Dette er a₂.');if(level===1)return result(`a₀=${a}, aₙ₊₁=2aₙ+${b}. Finn a₂.`,4*a+3*b,'','Oppdater to ganger.',`a₁=${2*a+b}, a₂=${4*a+3*b}.`,2*a+b,'Dette er bare første oppdatering.');return result(`En likevekt L oppfyller L=0,5L+${b}. Finn L.`,2*b,'','Samle L-leddene.',`0,5L=${b}, altså L=${2*b}.`,b,'Husk at begge ledd på høyre side bidrar.');}},
 {id:'integral',title:'Integral som grenseverdi',summary:'Fra summer til fortegnet areal og akkumulering.',
 theory:['En Riemannsum summerer f(xᵢ*)Δxᵢ over en partisjon. Når største delintervall går mot null og grensen finnes, får vi det bestemte integralet.','Integralets fortegn avhenger av funksjonsverdiene: bidrag under x-aksen er negative. Geometrisk areal krever integralet av |f| eller oppdeling ved nullpunkter.','I bevegelse langs en linje gir integralet av den fortegnede hastigheten v forflytningen. Integral av farten |v| gir tilbakelagt strekning. Begge måles i meter når hastigheten er i m/s og tiden i sekunder.'],
 example:['For f(x)=x på [0,2] er integralet lik arealet av en trekant.','Grunnlinjen og høyden er begge 2.','∫₀² x dx = 2.'],
 activity:'Undersøk f(x)=x på [0,2] med venstre- og høyresummer for n = 2, 4 og 8. Lag tabell og tegning, beskriv hva som skjer når n øker, og begrunn grenseverdien geometrisk. Tolk også integralene dersom v(t)=t m/s og v(t)=t−1 m/s for 0≤t≤2 s. Finn forflytning og tilbakelagt strekning i begge tilfeller.',
 criteria:['Konstruerer og sammenligner riktige summer og grenseverdi.','Forklarer integralets tolkning med enheter og fortegn.'],model:'Med Δx = 2/n blir venstresummen 2(n−1)/n og høyresummen 2(n+1)/n. Begge går mot 2, som også er trekantens areal. Med v(t)=t er både forflytningen og strekningen 2 m. Med v(t)=t−1 opphever de fortegnede trekantarealene hverandre: forflytningen er 0 m, mens strekningen er 1 m.',teacher:'Forkunnskaper: areal og grenser. Vanlig feil: forveksle fortegnet areal med geometrisk areal.',goals:['Gjøre rede for integral som grenseverdi av summer og tolke grenseverdien.'],
 task(level,seed){let a=2+n(seed,7);if(level===0)return result(`f(x)=${a} på [0,3]. Finn ∫₀³ f(x) dx.`,3*a,'','Bruk rektangelets areal.',`${a}·3=${3*a}.`,a,'Husk intervallbredden.');if(level===1)return result(`Finn ∫₀² ${a}x dx.`,2*a,'','Bruk arealet av trekanten.',`2·${2*a}/2=${2*a}.`,4*a,'Trekantens areal er halvparten av rektangelets.');return result(`f(x)=${a} på [0,1) og f(x)=−${a} på [1,2]. Hva er ∫₀² f(x) dx?`,0,'','Ta hensyn til fortegnet.',`${a}−${a}=0.`,2*a,'Dette er geometrisk areal, ikke fortegnet integral.');}},
 {id:'fundamentalteorem',title:'Analysens fundamentalteorem',summary:'Knytt akkumulering, derivasjon og integrasjon sammen.',
 theory:['Hvis f er kontinuerlig, er F(x)=∫ₐˣ f(t)dt deriverbar og F′(x)=f(x). Dette er den første delen av analysens fundamentalteorem.','Hvis G er en antiderivert til f, gir andre del ∫ₐᵇ f(x)dx=G(b)−G(a). Konstantleddet i G faller bort.','Teoremet knytter lokal endringsrate til akkumulert endring. Når v er en kontinuerlig hastighet, er integralet av v endringen i posisjon.'],
 example:['La f(x)=2x og G(x)=x².','∫₁³ 2x dx = G(3)−G(1) = 9−1 = 8.','Derivasjon av G gir tilbake f.'],activity:'Definer F(x)=∫₁ˣ 2t dt. Finn F(x), deriver uttrykket og tolk F for x både over og under 1. Forklar hvorfor F(1)=0 og sammenlign med G(x)=x² som antiderivert.',criteria:['Bruker begge deler av teoremet med gyldige forutsetninger.','Begrunner sammenhengen mellom F og en generell antiderivert.'],model:'F(x)=x²−1, så F′(x)=2x og F(1)=0. F og G har samme deriverte og skiller seg med konstanten −1. For x<1 er integralgrensene ombyttet; fortegnet må vurderes sammen med integranden.',teacher:'Forkunnskaper: derivasjon og integral. Vanlig feil: glemme nedre grense.',goals:['Gjøre rede for analysens fundamentalteorem og konsekvenser.'],
 task(level,seed){let a=1+n(seed,5);if(level===0)return result(`F(x)=${a}x² er en antiderivert. Hva er F′(2)?`,4*a,'','Deriver før du setter inn 2.',`F′(x)=${2*a}x, og F′(2)=${4*a}.`,2*a,'Dette er koeffisienten, ikke verdien i 2.');if(level===1)return result(`Beregn ∫₀² ${2*a}x dx.`,4*a,'','Bruk antiderivert ax².',`${a}·2²−${a}·0²=${4*a}.`,2*a,'Husk å kvadrere øvre grense.');return result(`Beregn ∫₁³ ${2*a}x dx.`,8*a,'','Trekk verdien ved nedre grense fra verdien ved øvre.',`${a}·3²−${a}·1²=${8*a}.`,9*a,'Verdien ved nedre grense må trekkes fra.');}},
 {id:'numerisk',title:'Numerisk integrasjon',summary:'Utvikle og undersøk algoritmer for tilnærming.',
 theory:['Trapesmetoden tilnærmer grafen med rette linjestykker. Med n like intervaller er Tₙ = h[(f(a)+f(b))/2 + Σᵢ₌₁ⁿ⁻¹ f(a+ih)], der h=(b−a)/n.','En algoritme beregner h, summerer endepunkter med halv vekt og indre punkter med hel vekt, og multipliserer summen med h. Test først på en konstant eller lineær funksjon.','En finere partisjon gir ofte bedre tilnærming for glatte funksjoner, men endringen mellom to estimater er ikke i seg selv et bevis på en bestemt feilgrense.'],
 example:['Bruk ett trapes for f(x)=x² på [0,2].','T₁=2·(0+4)/2=4.','Eksakt integral er 8/3; tilnærmingen er for stor.'],activity:'Utvikle et program for trapesmetoden for f(x)=x² på [0,2]. Test n=1, 2, 4 og 8, sammenlign med eksakt verdi, og forklar hvorfor metoden overvurderer her. Dokumenter kode og test med en lineær funksjon.',criteria:['Programmet beregner trapeser korrekt og er testet.','Sammenligner feil og begrunner retningen på avviket.'],model:'T₁=4, T₂=3, T₄=2,75 og T₈=2,6875; eksakt verdi er 8/3. Funksjonen er konveks, så kordene ligger over grafen. Med f(x)=x gir metoden 2 for ethvert positivt heltall n.',teacher:'Forkunnskaper: løkker og areal. Vanlig feil: telle endepunktene dobbelt.',goals:['Utvikle algoritmer for numerisk integrasjon og bruke programmering til å utføre dem.'],
 task(level,seed){let a=1+n(seed,6);if(level===0)return result(`Ett trapes har bredde 2 og parallelle sider ${a} og ${a+2}. Finn arealet.`,2*a+2,'','Gjennomsnittlig høyde ganger bredde.',`2·(${a}+${a+2})/2=${2*a+2}.`,a+1,'Dette er gjennomsnittlig høyde.');if(level===1)return result(`Hva er intervallbredden når [0,${a*4}] deles i 4 like deler?`,a,'','Del lengden på antall deler.',`${a*4}/4=${a}.`,a*4,'Dette er hele intervallengden.');return result(`Bruk ett trapes for f(x)=${a}x² på [0,2]. Hva er tilnærmingen?`,4*a,'','Bruk endepunktsverdiene.',`2·(0+${4*a})/2=${4*a}.`,2*a,'Endepunktsverdiene er 0 og 4a.');}},
 {id:'modeller',title:'Modellering med reelle datasett',summary:'Velg funksjoner, tilpass data og vurder gyldighet.',
 theory:['Valg av modell bør bygge på både situasjon og data. Lineær vekst innebærer konstant absolutt endring; eksponentiell vekst innebærer konstant relativ endring. Andre fenomener kan kreve periodiske modeller.','Regresjon anslår parametre for en valgt modell. Undersøk residualer og forklaringsgrad, men la ikke ett mål alene avgjøre modellvalget.','Ekstrapolasjon utenfor dataintervallet kan være usikker. Registreringsmetode, målefeil, tilfeldige variasjoner og mekanismer som endrer seg, påvirker tolkningen.'],
 example:['Modellen f(t)=100·1,02ᵗ gir 100 ved t=0 og 102 ved t=1.','Absolutt økning første år er 2; relativ økning er 2 %.','Det er en illustrasjon, ikke et observert datasett.'],activity:'Hent en tidsserie med minst ti årlige observasjoner fra Statistisk sentralbyrå, for eksempel folkemengde i en kommune (ssb.no/statbank, tabell 07459). Oppgi variabel, periode, uttrekk og nedlastingsdato. Tilpass en lineær og en eksponentiell modell, undersøk residualene og drøft hvilken som passer og hvorfor. Vurder usikkerhet ved ekstrapolasjon.',criteria:['Dokumenterer reelle data, modeller og beregninger slik at de kan etterprøves.','Sammenligner residualer og vurderer forutsetninger og gyldighetsområde.'],model:'En mulig konklusjon er at den eksponentielle modellen har systematisk krummede residualer og derfor ikke beskriver serien godt. Konklusjonen må bygge på de faktiske dataene og tilpasningene eleven har hentet; ingen modell er automatisk best.',teacher:'Forkunnskaper: regresjon og vekstfaktor. Vanlig feil: velge modell utelukkende etter R². Sikre at utvalgte data og kilde følger besvarelsen.',goals:['Modellere og analysere situasjoner med ulike funksjoner og reelle datasett.'],
 task(level,seed){let a=100+10*n(seed,8),b=2+n(seed,5);if(level===0)return result(`f(t)=${a}+${b}t. Hva er f(2)?`,a+2*b,'','Sett t=2.',`${a}+${b}·2=${a+2*b}.`,a+b,'Dette er verdien ved t=1.');if(level===1)return result(`En observasjon er ${a+b} og modellen gir ${a}. Hva er residualen observasjon minus modell?`,b,'','Trekk modellverdien fra observasjonen.',`${a+b}−${a}=${b}.`,-b,'Fortegnet blir feil når rekkefølgen snus.');return result(`f(t)=${a}·1,1ᵗ. Hvor stor er økningen fra t=0 til t=2?`,round(a*0.21),'','Beregn f(2)−f(0).',`${a}·1,1²−${a}=${round(a*0.21)}.`,round(a*1.21),'Dette er sluttverdien, ikke økningen.');}},
 {id:'modellendring',title:'Derivasjon og integrasjon av modeller',summary:'Tolk endringsrate og akkumulert endring i datasammenheng.',
 theory:['Den deriverte av en modell angir momentan endringsrate i enhet per tidsenhet. Endringsrate er ikke det samme som selve størrelsen.','Integral av en rate over et tidsintervall gir akkumulert endring. Enheten blir ratens enhet multiplisert med tidsenheten.','En modell tilpasset observerte data er en tilnærming. Derivasjon kan forsterke støy, og både integral og tolkning påvirkes av modellvalg og definisjonsområde.'],example:['En modell for tilsig er q(t)=2t+4 liter per time.','q′(t)=2 liter per time².','I de første 3 timene er tilsiget ∫₀³ (2t+4)dt=21 liter.'],activity:'Bruk et reelt tidsseriedatasett med regelmessige målinger, for eksempel timesverdier for temperatur fra Norsk klimaservicesenter (seklima.met.no). Dokumenter kilde, sted, tidspunkt og enheter. Tilpass en glatt modell T(t), analyser T′ og ∫(T−0)dt over måleintervallet, og forklar hva gradtimer betyr og hva modellen ikke viser.',criteria:['Dokumenterer data, modell, derivasjon og integral med enheter.','Tolker resultatene og vurderer modellens begrensninger.'],model:'Hvis en tilpasset modell i en periode er T(t)=2t+4 °C med t i timer, er T′=2 °C/time og integralet over [0,3] lik 21 °C·timer. Eksemplet illustrerer metoden; reelle verdier må komme fra elevens datasett.',teacher:'Forkunnskaper: modellering og integral. Vanlig feil: tolke integralet av temperatur som temperatur. Avklar fortegn og basisnivå.',goals:['Anvende derivasjon og integrasjon til å analysere og tolke egne modeller av reelle datasett.'],
 task(level,seed){let a=1+n(seed,6);if(level===0)return result(`f(t)=${a}t². Hva er f′(1)?`,2*a,'','Deriver og sett t=1.',`f′(t)=${2*a}t, så f′(1)=${2*a}.`,a,'Dette er f(1), ikke endringsraten.');if(level===1)return result(`En konstant rate er ${a} liter per time i 3 timer. Hva er akkumulert mengde?`,3*a,'liter','Integrer raten over tiden.',`${a}·3=${3*a} liter.`,a,'Dette er raten, ikke mengden.');return result(`q(t)=${a}t liter per time. Hvor mange liter tilføres fra t=0 til t=2?`,2*a,'liter','Integrer q fra 0 til 2.',`[${a}t²/2]₀²=${2*a} liter.`,4*a,'Dette er rektangelets areal, men grafen gir en trekant.');}},
 {id:'omdreining',title:'Funksjonsanalyse og omdreiningslegemer',summary:'Bruk integral til å beregne volum og tolk resultatet.',
 theory:['Derivasjon kan gi stigning, ekstremalpunkter og krumning; integrasjon kan beskrive akkumulering og areal. Kontroller også randpunkter og definisjonsmengde.','Når området mellom y=f(x) og x-aksen roteres om x-aksen, er volumet V=π∫ₐᵇ[f(x)]²dx. Kvadratet kommer av at hvert tverrsnitt er en sirkel.','Med et hull brukes skivemetoden med ytre radius R og indre radius r: V=π∫ₐᵇ(R²−r²)dx. Radiene måles fra rotasjonsaksen. For en deriverbar og ikke-negativ radiusprofil r er arealet av den krumme flaten S=2π∫ₐᵇ r(x)√(1+r′(x)²) dx. Faktorene er omkretsen og buelengdeelementet.'],example:['Roter området under f(x)=x på [0,2] om x-aksen.','V=π∫₀² x²dx=8π/3.','Dette stemmer med kjegleformelen πr²h/3 for r=2 og h=2.'],activity:'En beholder har indre radius r(x)=2−x/2 cm for 0≤x≤4 cm. Skisser tverrsnittet og beregn volumet ved rotasjon om x-aksen. Bruk r′ til å forklare hvorfor radius avtar med konstant rate, og beregn også arealet av den krumme innerflaten ved integrasjon. Kontroller begge mål geometrisk og vurder modellen.',criteria:['Setter opp integralet med riktig radius, grenser og enhet.','Bruker den deriverte til å tolke profilen, kontrollerer volum og flateareal geometrisk og vurderer modellen.'],model:'V=π∫₀⁴(2−x/2)²dx=16π/3 cm³. Legemet er en kjegle med radius 2 cm og høyde 4 cm, som gir π·2²·4/3=16π/3 cm³. Radius avtar med 0,5 cm per cm. Med r′=−1/2 gir flateintegralet 4π√5 cm². Kjeglas sidelengde er √(4²+2²)=2√5 cm, så flatearealet er også π·2·2√5=4π√5 cm². Modellen idealiserer hjørner og veggtykkelse.',teacher:'Forkunnskaper: integral og sirkelareal. Vanlig feil: integrere radius uten å kvadrere den.',goals:['Analysere funksjoner ved derivasjon og integrasjon og beregne mål av omdreiningslegemer.'],
 task(level,seed){let a=1+n(seed,5);if(level===0)return result(`f(x)=${a}x². Hva er f′(2)?`,4*a,'','Bruk potensregelen.',`f′(x)=${2*a}x, så f′(2)=${4*a}.`,2*a,'Sett også inn x=2.');if(level===1)return result(`Et område med radius ${a} roteres om x-aksen over lengden 2. Hva er volumet delt på π?`,2*a*a,'','Tverrsnittet er en sirkel.',`V/π=${a}²·2=${2*a*a}.`,a===1?1:2*a,'Radius må kvadreres.');return result(`Området under f(x)=${a}x fra 0 til 1 roteres om x-aksen. Hva er volumet delt på π? Avrund til to desimaler.`,round(a*a/3),'','Integrer f(x)².',`V/π=∫₀¹ ${a*a}x² dx=${a*a}/3≈${round(a*a/3)}.`,round(a/2),'Dette svarer til arealet under f, ikke volumet.');}} ,{id:'parameter',title:'Parameterframstillinger og bevegelse',summary:'Beskriv kurver, hastighet og akselerasjon med vektorer.',
 theory:['En parameterframstilling r(t)=(x(t), y(t)) angir både posisjon og bevegelsesretning når t øker. Å eliminere parameteren kan gi en kurvelikning, men beskriver ikke nødvendigvis hele bevegelsen.','Når t måles i sekunder og posisjon i meter, er hastighetsvektoren v(t)=r′(t), farten |v(t)| og akselerasjonen a(t)=r″(t). Fart er en skalar, mens hastighet har retning.','I en kastmodell uten luftmotstand er horisontal akselerasjon null og vertikal akselerasjon konstant. Modellen gjelder fram til gjenstanden treffer bakken.'],
 example:['r(t)=(3t, 4t−t²) meter for 0≤t≤4 s.','v(t)=(3,4−2t), a(t)=(0,−2).','Ved t=2 s er hastigheten (3,0) m/s og farten 3 m/s.'],
 activity:'En gjenstand følger r(t)=(3t, 4t−t²) meter med t i sekunder fram til den treffer bakken. Skisser banen med bevegelsesretning, finn hastighet, fart og akselerasjon, og bestem maksimal høyde og nedslagspunkt. Undersøk hvordan endret vertikal starthastighet påvirker banen og vurder modellens forutsetninger.',
 criteria:['Finner og tolker parameterframstilling, hastighet, fart og akselerasjon med riktige enheter.','Begrunner maksimum og nedslag, og undersøker hvordan en parameter og modellforutsetningene virker.'],
 model:'y(t)=0 gir nedslag ved t=4 s, etter utskytingen. y′(t)=4−2t gir toppunkt ved t=2 s med posisjon (6,4) m. Nedslagspunktet er (12,0) m. Hastighetsvektoren er v=(3,4−2t) m/s og akselerasjonen a=(0,−2) m/s². Farten er √(9+(4−2t)²) m/s og ved nedslag 5 m/s. Med vertikal startfart u m/s (u>0) og samme akselerasjon blir maksimal høyde u²/4 m og nedslagstiden u s. Verdien −2 m/s² er en valgt modellparameter. Luftmotstand er utelatt.',teacher:'Forkunnskaper: derivasjon og vektorer. Vanlig feil: forveksle fart og vertikal hastighet. Spør hva parameterintervallet betyr.',goals:['Anvende parameterframstillinger til kurver og naturvitenskapelige problemer, inkludert fart og akselerasjon.'],
 task(level,seed){let a=2+n(seed,6),b=1+n(seed,5);if(level===0)return result(`En partikkel har x(t)=${a}t meter. Hva er x(2)?`,2*a,'m','Sett t=2.',`${a}·2=${2*a} m.`,a,'Dette er posisjonen ved t=1.');if(level===1)return result(`En partikkel har y(t)=${a}t² meter. Hva er den vertikale hastigheten ved t=2 sekunder?`,4*a,'m/s','Deriver y(t) og sett inn t=2.',`y′(t)=${2*a}t, så y′(2)=${4*a} m/s.`,2*a,'Husk å sette inn t=2 etter derivasjon.');return result(`En partikkel har r(t)=(${a}t, ${b}t²). Hva er akselerasjonens vertikale komponent?`,2*b,'m/s²','Deriver y-koordinaten to ganger.',`y″(t)=2·${b}=${2*b} m/s².`,b,'Andrederivert av bt² er 2b.');}},
 {id:'romvektorer',title:'Vektorer i rommet',summary:'Bruk vektorregning til lengder, vinkler og geometri.',
 theory:['For u=(u₁,u₂,u₃) og v=(v₁,v₂,v₃) regner vi komponentvis med addisjon og skalarmultiplikasjon. Lengden er |u|=√(u₁²+u₂²+u₃²).','Skalarproduktet u·v=u₁v₁+u₂v₂+u₃v₃=|u||v|cos θ. To ikke-null vektorer står vinkelrett når skalarproduktet er null.','Kryssproduktet u×v står vinkelrett på begge vektorer og har lengde |u||v|sin θ. Dermed kan det brukes til å finne parallellogramareal og normalvektor til et plan.'],
 example:['u=(1,2,2) og v=(2,−1,0).','u·v=2−2+0=0, så vektorene står vinkelrett.','|u|=√(1+4+4)=3.'],
 activity:'Tre punkter A=(0,0,0), B=(2,0,0) og C=(0,3,0) spenner ut en trekant. Finn areal, en normalvektor og en likning for planet gjennom punktene. Flytt C til (0,3,4), og undersøk hva som endres. Begrunn begge arealene på to måter.',
 criteria:['Bruker vektorregneregler og begrunner areal og planlikning.','Kontrollerer med en annen metode og forklarer virkningen av endringen.'],
 model:'Først er AB×AC=(0,0,6), arealet 3 og planet z=0. Med C=(0,3,4) blir AB×AC=(0,−8,6), med lengde 10, så arealet er 5. AB står vinkelrett på AC, så også grunnlinje 2 og høyde 5 gir areal 5. Et plan er −8y+6z=0.',teacher:'Forkunnskaper: planvektorer og Pytagoras. Vanlig feil: forveksle skalarprodukt og kryssprodukt.',goals:['Utforske regneregler for vektorer i rommet og bruke vektorer til å beregne størrelser.'],
 task(level,seed){let a=1+n(seed,5),b=2+n(seed,5);if(level===0)return result(`u=(${a}, ${b}, 0). Hva er første komponent i 2u?`,2*a,'','Multipliser hver komponent med 2.',`2·${a}=${2*a}.`,a,'Vektoren må skaleres.');if(level===1)return result(`u=(${a},0,0) og v=(${b},1,0). Hva er u·v?`,a*b,'','Multipliser samsvarende komponenter og summer.',`${a}·${b}+0·1+0·0=${a*b}.`,a+b,'Skalarprodukt er ikke summen av komponentene.');return result(`En trekant har vinkelrette sidevektorer med lengdene ${a*2} og ${b}. Hva er arealet?`,a*b,'','Halver produktet av grunnlinje og høyde.',`${a*2}·${b}/2=${a*b}.`,2*a*b,'Dette er arealet av parallellogrammet.');}},
 {id:'trigonometri',title:'Radianer og trigonometriske modeller',summary:'Utforsk identiteter og modeller periodisk variasjon.',
 theory:['En vinkel i radianer er buelengde delt på radius: θ=s/r. En hel omdreining er 2π radianer, tilsvarende 360°.','På enhetssirkelen er koordinatene (cos x, sin x), slik at sin²x+cos²x=1. Identiteter gjelder for alle verdier der uttrykkene er definert; løsninger av trigonometriske likninger må tilpasses intervallet.','En modell f(t)=d+A sin(ωt+φ) har amplitude |A|, midtlinje d og periode 2π/|ω| når ω≠0. Radianer er nødvendige i de vanlige derivasjonsreglene for sinus og cosinus.'],
 example:['f(t)=3+2 sin(πt/6), der t måles i timer.','Amplituden er 2 og perioden er 12 timer.','Maksimalverdien 5 nås først ved t=3 timer.'],
 activity:'Et pariserhjul har radius 10 m og sentrum 12 m over bakken. Én runde tar 40 s, og en passasjer starter i laveste punkt. Lag en sinus- eller cosinusmodell for høyden, bestem når passasjeren først er 17 m over bakken, og undersøk hvordan høyden endres. Drøft antakelser og bruk enhetssirkelen til å begrunne en identitet.',
 criteria:['Utleder en konsistent periodisk modell og løser problemet innenfor korrekt tidsintervall.','Begrunner en trigonometrisk identitet og tolker modellens parametre og forutsetninger.'],
 model:'h(t)=12−10 cos(πt/20). Høyden 17 gir cos(πt/20)=−0,5; første gang er t=40/3≈13,33 s. Modellen antar konstant vinkelhastighet. Enhetssirkelen gir sin²x+cos²x=1 ved Pytagoras.',teacher:'Forkunnskaper: funksjoner og enhetssirkel. Vanlig feil: blande grader og radianer eller glemme en løsning per periode.',goals:['Utforske radianer og trigonometriske funksjoner og identiteter og anvende dem på praktiske problemer.'],
 task(level,seed){let a=1+n(seed,5),b=2+n(seed,5);if(level===0)return result(`En sirkel har radius ${a} m. Hvor lang er buen ved vinkelen 2 radianer?`,2*a,'m','Bruk s=rθ.',`s=${a}·2=${2*a} m.`,a,'Dette er radiusen.');if(level===1)return result(`En periodisk modell f(t)=${b}+${a} sin(πt/4) beskriver høyde. Hva er amplituden?`,a,'','Amplituden er absoluttverdien av sinuskoeffisienten.',`Amplituden er ${a}.`,a===b?b+1:b,'Konstantleddet beskriver midtlinjen.');return result(`En periodisk modell er f(t)=${b}+${a} sin(πt/4). Hva er perioden?`,8,'','Bruk perioden 2π/ω.',`2π/(π/4)=8.`,4,'Dette er halvparten av perioden.');}},
 {id:'bevis',title:'Matematiske bevis',summary:'Analyser argumenter og utvikle egne generelle bevis.',
 theory:['Et bevis viser at en påstand gjelder for alle objekter i et presist angitt område. Eksempler kan styrke en formodning, men ett moteksempel er nok til å avkrefte en universell påstand.','Direkte bevis starter med forutsetningene og bruker gyldige slutninger fram til konklusjonen. Motsetningsbevis og induksjon er andre strategier som må begrunnes med sine egne logiske trinn.','Induksjon krever både et basissteg og et induksjonssteg: anta påstanden for et vilkårlig n og vis at den følger for n+1. Induksjonshypotesen gjelder ikke automatisk for alle tall uten basissteget.'],
 example:['Påstand: Summen av to partall er et partall.','Skriv tallene 2m og 2n, der m og n er heltall.','Summen er 2(m+n), som er delelig med 2.'],
 activity:'Undersøk påstanden 1+3+…+(2n−1)=n² for alle positive heltall n. Forklar den bærende ideen i et geometrisk argument med kvadrater, og utvikle deretter ditt eget induksjonsbevis med basissteg og induksjonssteg. Vurder hvorfor et mønster for n=1,2,3 alene ikke er et bevis.',
 criteria:['Forklarer ideen i det geometriske argumentet og knytter hvert trinn til påstanden.','Utvikler et fullstendig induksjonsbevis med eksplisitt basissteg og gyldig induksjonssteg.'],
 model:'Et n×n-kvadrat kan bygges fra et (n−1)×(n−1)-kvadrat ved å legge til 2n−1 ruter. Basis: n=1 gir 1=1². Anta summen lik n². Neste sum er n²+(2n+1)=(n+1)². Dermed gjelder påstanden for alle positive heltall ved induksjon.',teacher:'Forkunnskaper: algebra og heltall. Vanlig feil: verifisere noen tilfeller og kalle det bevis, eller utelate basissteget.',goals:['Analysere matematiske bevis, forklare bærende ideer og utvikle egne bevis.'],
 task(level,seed){let a=1+n(seed,8);if(level===0)return result(`Et partall skrives 2k. Hva er tallet når k=${a}?`,2*a,'','Sett inn k.',`2·${a}=${2*a}.`,a,'k er halvparten av partallet.');if(level===1)return result(`Hva er summen av de ${a} første positive oddetallene?`,a*a,'','Bruk formelen n².',`${a}²=${a*a}.`,a===1?2:a,'Summen er kvadratet av antallet ledd.');return result(`I induksjonssteget fra n til n+1 legges neste oddetall 2n+1 til. Hva er neste oddetall når n=${a}?`,2*a+1,'','Sett n inn i 2n+1.',`2·${a}+1=${2*a+1}.`,2*a-1,'Dette er det n-te oddetallet, ikke det neste.');}}

 ]
};
